function abbreviateProduct(left, right) {
  let twos = 0;
  let fives = 0;
  for (let i = left; i <= right; i++) {
    for (let x = i; x % 2 === 0; x /= 2) twos++;
    for (let x = i; x % 5 === 0; x /= 5) fives++;
  }
  const zeros = Math.min(twos, fives);
  let twosLeft = zeros;
  let fivesLeft = zeros;
  let suffix = 1;
  let exact = 1;
  let big = false;
  let prefix = 1;
  for (let i = left; i <= right; i++) {
    let x = i;
    while (twosLeft > 0 && x % 2 === 0) {
      x /= 2;
      twosLeft--;
    }
    while (fivesLeft > 0 && x % 5 === 0) {
      x /= 5;
      fivesLeft--;
    }
    suffix = (suffix * x) % 100000;
    if (!big) {
      exact *= x;
      big = exact >= 1e10;
    }
    prefix *= i;
    while (prefix >= 100000) {
      prefix /= 10;
    }
  }
  if (!big) {
    return `${exact}e${zeros}`;
  }
  const head = Math.floor(prefix);
  const tail = String(suffix).padStart(5, '0');
  return `${head}...${tail}e${zeros}`;
}

