function abbreviateProduct(left, right) {
  let product = 1n;
  for (let i = left; i <= right; i++) product *= BigInt(i);
  const text = product.toString();
  const digits = text.replace(/0+$/, '');
  const zeros = text.length - digits.length;
  if (digits.length <= 10) return digits + 'e' + zeros;
  return digits.slice(0, 5) + '...' + digits.slice(-5) + 'e' + zeros;
}

